local ParkourBossMainRankNode = Class('ParkourBossMainRankNode')

--region lifecycle

function ParkourBossMainRankNode:__init()
    self.activityContentId = 1
    self.activityUuid = 1
    self.homeData = nil
    self.rankType = -1 ---初始是分榜
    self.rankType = checkNumber(KCookie.Get("ParkourBossMainRankNode"))
    if checkNumber(self.rankType) <= 0 then
        self.rankType = RankType.PARTITION
    end
    self.scheduleId = 1
    KCookie.RemoveAllListener("ParkourBossMainRankNode")
    ---@type UnityEngine.RectTransform
    self.TxtTimeTotal = nil
    self.countdown = nil
end

function ParkourBossMainRankNode:__delete()
    self.activityContentId = nil
    self.homeData = nil
end

function ParkourBossMainRankNode:Awake()
    self.TxtTimeTotal = self.TabToggleUpGroup.transform.parent:Find("TxtTimeTotal")
    CfUtils.SetActive(self.LayoutListAndMyselef, false)
    self:InitHandler()
end

function ParkourBossMainRankNode:RemoveTimer()
    ---@type Engine.Modules.CDTimerModule
    local cdTimerModule = CDTimerModule.GetInstance()
    if not isNull(self.countdown) then
        cdTimerModule:RemoveCD(self.countdown)
    end
    self.countdown = nil
end

function ParkourBossMainRankNode:StartCountDown()
    ---@type Engine.Modules.CDTimerModule
    local cdTimerModule = CDTimerModule.GetInstance()
    self:RemoveTimer()
    self.countdown = cdTimerModule:AddCD(1, function(count, id, elapsed)
        if self.homeData then
            if self.rankType == RankType.PARTITION then
                self.homeData.splitRankCloseTime = math.max(checkNumber(self.homeData.splitRankCloseTime) - elapsed, 0)
                if checkNumber(self.homeData.splitRankCloseTime) <= 0 then
                    ---结束了
                    self:RemoveTimer()
                end
                CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS2(checkNumber(self.homeData.splitRankCloseTime)))
            else
                ---全局的活动总倒计时
                local closeTime = checkNumber(self.closeTime)
                self.closeTime = math.max(checkNumber(self.closeTime) - elapsed, 0)
                if closeTime <= 0 then
                    self:RemoveTimer()
                end
                CfUtils.FillText(self.TxtTimeTotal, CfUtils.GetTimeHMS2(checkNumber(self.closeTime)))
            end
        end
    end, CountDownTime, false, true)
end

function ParkourBossMainRankNode:Start()
    self:StartCountDown()
end

function ParkourBossMainRankNode:OnDestroy()
    KCookie.Set("ParkourBossMainRankNode", checkInt(self.rankType))
    self:RemoveTimer()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function ParkourBossMainRankNode:InitHandler()
    ---@type ActivityCakeShopBossRankMyCell
    self._myRankScr = CfUtils.GetLuaScr(self.MyRanking, "Game.UI.ActivityCakeShopDialog.Cell.ActivityCakeShopBossRankMyCell")
    --CfUtils.SetActive(self.BtnRank.transform:Find("SelectGroup"), self.rankType == RankType.PARTITION)
    --CfUtils.SetActive(self.BtnTotalRank.transform:Find("SelectGroup"), self.rankType == RankType.ALL_RANK)
end

---OnRankTypeButtonAction
---点击榜单类型
function ParkourBossMainRankNode:OnRankTypeButtonAction(rankType)
    --if self.rankType == rankType then
    --    return
    --end
    self.rankType = rankType
    CfUtils.SetActive(self.TxtTimeTotal, self.rankType == RankType.ALL_RANK)
    CfUtils.SetActive(self.BtnRank.transform:Find("SelectGroup"), self.rankType == RankType.PARTITION)
    CfUtils.SetActive(self.BtnTotalRank.transform:Find("SelectGroup"), self.rankType == RankType.ALL_RANK)
    CfUtils.SetActive(self.TabToggleUpGroup, rankType == RankType.PARTITION)
    --先把列表清理下
    GameUtils.ReloadData(self.LoopView, 0)
    if rankType == RankType.PARTITION then
        self:FreshListByListType()
    else
        CfUtils.FillText(self.TxtTimeTotal, CfUtils.GetTimeHMS2(checkNumber(self.closeTime)))
        self.data = self.homeData
        self._rankInfo = self.homeData.rank
        self:RefreshUI()
    end
end

---FreshToggleTab
---刷新顶部的标签信息
function ParkourBossMainRankNode:FreshToggleTab(rankType)
    --if rankType == RankType.PARTITION then
        CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS2(checkNumber(self.data.splitRankCloseTime)))
        local toggleData = {}
        local config = checkTable(self.data.splitRankConfig)
        local scheduleId = checkInt(self.homeData.scheduleId)
        local rankConfig = table.values(config)
        SortByMember(rankConfig, "order")
        if scheduleId == 0 then
            scheduleId = checkInt(rankConfig[#rankConfig].id)
        end
        for i, v in pairs(rankConfig) do
            local isLock = checkInt(v.id) > scheduleId
            table.insert(toggleData,{
                id = checkNumber(v.id),
                order = checkInt(v.order),
                isLock = isLock,
                text = localize('第_num_期', {_num_ = v.order}),
                checkFunc = function()
                    if isLock then GameUtils.Toast(localize('当前暂未开启'))  end
                    return (not isLock)
                end,
                func = function()
                    self.scheduleId = checkInt(v.order)
                    GameUtils.ReloadData(self.LoopView, 0)
                    self:FreshListByListType()
                end
            })
        end
        self._toggleData = toggleData
        ---@type CommonTabToggleUp
        local env = CfUtils.GetLuaScr(self.CommonTabToggleUp.gameObject, CommonTabToggleUpEnvPath)
        if isNull(env) then return end
        env:FillToggles(self._toggleData, self.scheduleId)
    --end
end
function ParkourBossMainRankNode:FreshListByListType()
    ---请求数据
    GameUtils.Request("activityTinyWorld/splitRankList", {
        activityUuid = self.activityUuid,
        scheduleId = self.scheduleId,
    }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        self.data = response.data
        self._rankInfo = self.data.rankInfo
        self:RefreshUI()
    end)
end

function ParkourBossMainRankNode:InitData()
    self._rankInfo = self.homeData.rank
    SetButtonAction(self.BtnTotalRank, function()
        self:OnRankTypeButtonAction(RankType.ALL_RANK)
    end)
    SetButtonAction(self.BtnRank, function()
        self:OnRankTypeButtonAction(RankType.PARTITION)
    end)
    --self:FreshToggleTab(RankType.PARTITION)
    --self:OnRankTypeButtonAction(RankType.PARTITION)
    self:FreshToggleTab(self.rankType)
    self:OnRankTypeButtonAction(self.rankType)
    CfUtils.SetActive(self.TxtTimeTotal, self.rankType == RankType.ALL_RANK)
end
--endregion init

