--endregion handler

--region public
function ParkourBossMainRankNode:Refresh(data, activityContentId, activityUuid, closeTime)
    self.data = data
    self.activityUuid = activityUuid
    self.homeData = clone(data)
    self.activityContentId = checkNumber(activityContentId)
    self.closeTime = checkNumber(closeTime)
    self:InitData()
    CfUtils.SetActive(self.controller, true)
end
--endregion public

--region private
function ParkourBossMainRankNode:OnGetItemByIndex(listView, index)
    local luaIndex = index + 1
    local cellData = self._rankInfo[luaIndex]
    local cell = listView:NewListViewItem("Cell")
    ---@type ActivityCakeShopBossRankCell
    local scr = CfUtils.GetLuaScr(cell, "Game.UI.ActivityCakeShopDialog.Cell.ActivityCakeShopBossRankCell")
    scr:Refresh(cellData, luaIndex, self.rankType == RankType.ALL_RANK and BossRankType.ParkMiniWorldBoss or BossRankType.ParkMiniWorldBossPartition, self.activityContentId)
    return cell
end

function ParkourBossMainRankNode:RefreshRankList()
    ---@type MidFestivalBossParameterVo
    local parametersVo =  CfUtils.GetCfVo(AutoIds.IdSetting6452, "ActivityCakeBossParamsVo", 2)
    local showCount = math.min(checkNumber(parametersVo.num), #self._rankInfo)

    if not self.LoopView.IsListViewInit then
        self.LoopView:InitListView(showCount, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopView, showCount)
    end
end

function ParkourBossMainRankNode:RefreshMyRank()
    self._myRankScr:Refresh(self.data, self.rankType == RankType.ALL_RANK and BossRankType.ParkMiniWorldBoss or BossRankType.ParkMiniWorldBossPartition, self.activityContentId)
end

function ParkourBossMainRankNode:RefreshUI()
    local isEmpty = next(self._rankInfo) == nil
    CfUtils.SetActive(self.LayoutListAndMyselef, not isEmpty)
    CfUtils.SetActive(self.EmptyNode, false)
    if isEmpty then
        CfUtils.SetActive(self.EmptyNode, true)
        return
    end

    self:RefreshRankList()
    self:RefreshMyRank()
end
--endregion private

--region get / set
--endregion get / set

return ParkourBossMainRankNode
